 const contractId=location.match(new RegExp(`^${basePath.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")}/contract/([^/]+)$`))?.[1]||null;const proposalId=location.match(new RegExp(`^${basePath.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")}/proposal/([^/]+)$`))?.[1]||null;
