 const active=data.contracts.filter(c=>["activo","pausado"].includes(norm(c.estado)));const revenue=data.invoices.filter(i=>{const d=new Date(i.fecha_emision),n=new Date();return d.getFullYear()===n.getFullYear()&&d.getMonth()===n.getMonth()}).reduce((s,i)=>s+Number(i.importe_a_pagar??i.monto??0),0);const pendingInvoices=data.invoices.filter(i=>["pendiente","enviada","impagada"].includes(norm(i.estado))).length;const cancellations=data.contracts.filter(c=>c.cancel_at_period_end&&norm(c.estado)!=="cancelado").length;const proposalPending=data.proposals.filter(p=>["submitted","in_review","clarification_requested"].includes(norm(p.status))).length;const incidents=data.contracts.filter(c=>Number(c.billing_failure_count||0)>0||Boolean(c.billing_blocked_at)).length;const fiscalIncomplete=data.companies.filter(c=>data.contracts.some(x=>x.company_id===c.id)&&!((c.legal_name||c.company_name)?.trim()&&c.cif_vat?.trim()&&c.address?.trim()&&c.postal_code?.trim()&&c.city?.trim()&&c.country?.trim())).length;const pendingFiscal=data.companyChangeRequests.filter(r=>norm(r.status)==="pending").length;const pendingProject=data.projectChangeRequests.filter(r=>norm(r.status)==="pending").length;const documentPending=data.invoices.filter(i=>!i.document_path&&!i.pdf_storage_path&&!i.electronic_document_storage_path).length;
