 const openDoc=async(path:string)=>{try{const {data,error}=await supabase.storage.from(INVOICE_BUCKET).createSignedUrl(path,600);if(error)throw error;if(!data?.signedUrl)throw new Error("No se ha podido generar el enlace seguro.");window.open(data.signedUrl,"_blank","noopener,noreferrer")}catch(e:any){toast.error(e?.message||"No se ha podido abrir el documento.")}};
 const uploadInvoice=async(i:Invoice,e:ChangeEvent<HTMLInputElement>)=>{const file=e.target.files?.[0];e.target.value="";if(!file)return;if(!perm.canUpdate){toast.error("No tienes permiso para modificar mantenimiento.");return}if(file.type!=="application/pdf"){toast.error("Solo se permiten PDF.");return}if(file.size>10*1024*1024){toast.error("El PDF no puede superar 10 MiB.");return}if(i.document_path){toast.error("La factura ya tiene un documento Modira asociado.");return}try{const path=`${i.id}/${crypto.randomUUID()}.pdf`;const {error:up}=await supabase.storage.from(INVOICE_BUCKET).upload(path,file,{contentType:"application/pdf",upsert:false});if(up)throw up;const {error:attach}=await supabase.rpc("attach_maintenance_invoice_document",{p_invoice_id:i.id,p_document_path:path});if(attach)throw attach;toast.success("PDF asociado a la factura.");await load(true);const {error:hash}=await supabase.functions.invoke(EDGE,{body:{action:"hash_maintenance_invoice_document",invoice_id:i.id}});if(hash)toast.warning("El PDF se ha asociado, pero no se pudo completar ahora la validación SHA-256.");else{toast.success("SHA-256 del documento registrado.");await load(true)}}catch(e:any){toast.error(e?.message||"No se ha podido asociar el PDF.");await load(true)}};
 const openRectification=(invoice:Invoice)=>{if(!perm.canCreate||!perm.canCreateInvoice){toast.error("No tienes permiso para crear facturas rectificativas de mantenimiento.");return}if(invoice.estado==="borrador"||!invoice.company_id||!invoice.document_path||!invoice.document_sha256){toast.error("La factura debe estar emitida y tener un PDF oficial con SHA-256 validado antes de rectificarla.");return}setRectifyingInvoice(invoice);setRectificationReason("");setRectificationCustomerSource("original_invoice");setRectificationSubtotal(String(Number(invoice.subtotal??0)));setRectificationIvaApplied(Boolean(invoice.iva_aplicado));setRectificationIvaPercentage(String(Number(invoice.iva_porcentaje??0)));setRectificationIrpfApplied(Boolean(invoice.irpf_aplicado));setRectificationIrpfPercentage(String(Number(invoice.irpf_porcentaje??0)));};
 const createRectification=async()=>{const original=rectifyingInvoice;if(!original)return;if(!perm.canCreate||!perm.canCreateInvoice){toast.error("No tienes permiso para crear facturas rectificativas de mantenimiento.");return}const subtotal=Number(rectificationSubtotal),iva=Number(rectificationIvaPercentage),irpf=Number(rectificationIrpfPercentage);if(!rectificationReason.trim()){toast.error("Indica el motivo de la rectificación.");return}if(!Number.isFinite(subtotal)||subtotal<0){toast.error("Introduce una base imponible válida, igual o superior a cero.");return}if(rectificationIvaApplied&&(!Number.isFinite(iva)||iva<0||iva>100)){toast.error("El IVA debe estar entre 0 y 100.");return}if(rectificationIrpfApplied&&(!Number.isFinite(irpf)||irpf<0||irpf>100)){toast.error("El IRPF debe estar entre 0 y 100.");return}try{setRectificationLoading(true);const {data:result,error}=await supabase.functions.invoke(EDGE,{body:{action:"create_maintenance_invoice_rectification",original_invoice_id:original.id,rectification_reason:rectificationReason.trim(),rectification_customer_data_source:rectificationCustomerSource,subtotal,iva_aplicado:rectificationIvaApplied,iva_porcentaje:rectificationIvaApplied?iva:0,irpf_aplicado:rectificationIrpfApplied,irpf_porcentaje:rectificationIrpfApplied?irpf:0}});if(error)throw error;if(!result?.ok||!result?.invoice?.id)throw new Error(result?.error||"No se ha podido crear la factura rectificativa.");toast.success(`Rectificativa ${result.invoice.serie}-${result.invoice.numero} creada.`);setRectifyingInvoice(null);setRectificationReason("");await load(true)}catch(e:any){console.error("[Maintenance] create rectification",e);let message=String(e?.message||"No se ha podido crear la factura rectificativa.");try{if(e?.context&&typeof e.context.json==="function"){const payload=await e.context.json();if(payload?.error)message=String(payload.error)}}catch{}toast.error(message);if(message.includes("se creó, pero no se pudo finalizar su PDF")){setRectifyingInvoice(null);setRectificationReason("")}await load(true)}finally{setRectificationLoading(false)}};
 const recoverRectificationDocument=async(invoice:Invoice)=>{if(!perm.canUpdate||!perm.canUpdateInvoice){toast.error("No tienes permiso para recuperar el PDF de una rectificativa de mantenimiento.");return}try{setRecoveringRectification(invoice.id);const {data:result,error}=await supabase.functions.invoke(EDGE,{body:{action:"ensure_maintenance_rectification_document",invoice_id:invoice.id}});if(error)throw error;if(!result?.ok)throw new Error(result?.error||"No se ha podido recuperar el PDF.");toast.success("PDF oficial de la rectificativa recuperado y validado.");await load(true)}catch(e:any){console.error("[Maintenance] recover rectification document",e);toast.error(e?.message||"No se ha podido recuperar el PDF.");await load(true)}finally{setRecoveringRectification(null)}};
 const resolveProject=async(id:string,action:"approve"|"reject")=>{if(!perm.canUpdate)return;try{setProjectAction(id);if(action==="approve"){const {error}=await supabase.rpc("approve_maintenance_contract_project_change",{p_request_id:id});if(error)throw error;toast.success("Solicitud de cambio de proyecto aprobada.")}else{if(!projectReason.trim()){toast.error("Indica el motivo del rechazo.");return}const {error}=await supabase.rpc("reject_maintenance_contract_project_change",{p_request_id:id,p_reason:projectReason.trim()});if(error)throw error;toast.success("Solicitud de cambio de proyecto rechazada.");setProjectRejecting(null);setProjectReason("")}await load(true)}catch(e:any){toast.error(e?.message||"No se ha podido gestionar la solicitud.")}finally{setProjectAction(null)}};
