 if(permLoading||loading)return <div className="min-h-screen bg-[#f7f8fb]"><main className="mx-auto max-w-[1500px] px-5 py-10 lg:px-8"><div className="flex items-center justify-center py-32 text-sm text-slate-500"><Loader2 className="mr-2 h-4 w-4 animate-spin text-[#102A66]"/>Cargando CRM de mantenimiento…</div></main></div>;
